mapper.select:
SELECT *
FROM farm_print_file



            user_id = #{filterUserId}


            user_id = #{userId}



        AND original_name LIKE CONCAT('%', #{fileName}, '%')


        AND UPPER(material_type) = #{materialType}


        AND is_folder = #{folder}



            AND parent_id = #{parentId}


            AND parent_id IS NULL



ORDER BY created_at DESC

SELECT *
FROM farm_print_file



            user_id = #{filterUserId}


            user_id = #{userId}



        AND original_name LIKE '%' || #{fileName} || '%'


        AND UPPER(material_type) = #{materialType}


        AND is_folder = #{folder}



            AND parent_id = #{parentId}


            AND parent_id IS NULL



ORDER BY created_at DESC

SELECT COUNT(*)
FROM farm_print_job
WHERE file_id = #{fileId}

  AND user_id = #{userId}


    AND status = #{status}

SELECT COUNT(*)
FROM farm_print_file
WHERE parent_id = #{parentId}

mapper.delete:
DELETE FROM farm_print_file
WHERE id = #{id}
  AND is_folder = 1
  AND is_default_folder = 0
  AND NOT EXISTS (
      SELECT 1
      FROM farm_print_file child
      WHERE child.parent_id = #{id}
  )

  AND user_id = #{userId}
